const csrf=cfg.csrf||'';
const admin=cfg.admin||{};
const permissions=Array.isArray(admin.permissions)?admin.permissions:[];
const state={finance:null,paymentAnalytics:null,paymentAnalyticsLoading:false,paymentAnalyticsFilter:{preset:'month',from:'',to:''},users:null,applications:null,applicationDetail:null,financeLoading:false,usersLoading:false,applicationsLoading:false,selectedAccount:0,search:'',risk:'all',referrer:'all',lastSavedAccountId:0,dossierSummaries:null,dossierDetail:null,dossierAccount:null,dossierTab:'checklist',dossierSelectedFile:0,dossierGps:'all',dossierDocs:'all',dossierPage:1,dossierPageSize:5,filters:{applications:{search:'',stage:'all',docs:'all'},payments:{search:'',status:'all'},receipts:{search:'',status:'all'},inventory:{search:'',status:'all'},audit:{from:'',to:'',user:'',module:'',type:'',search:''}}};
const q=s=>document.querySelector(s);
const qa=s=>Array.from(document.querySelectorAll(s));
const safe=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const num=v=>Number(v||0).toLocaleString('es-VE');
const money=v=>v===null||v===undefined||v===''?'—':'$'+Number(v||0).toLocaleString('es-VE',{minimumFractionDigits:2,maximumFractionDigits:2});
const bsMoney=v=>v===null||v===undefined||v===''?'—':'Bs. '+Number(v||0).toLocaleString('es-VE',{minimumFractionDigits:2,maximumFractionDigits:2});
const paymentMoney=p=>String(p?.currency||'USD').toUpperCase()==='BS'?bsMoney(p?.amount):money(p?.amount);
const pct=v=>Number(v||0).toLocaleString('es-VE',{minimumFractionDigits:0,maximumFractionDigits:1})+'%';
const today=()=>new Date().toISOString().slice(0,10);
const fmtDateTime=v=>{if(!v)return'—';const d=new Date(String(v).replace(' ','T'));return Number.isNaN(d.getTime())?String(v):d.toLocaleString('es-VE',{dateStyle:'medium',timeStyle:'short'})};
const toLocalInput=v=>{const d=v?new Date(String(v).replace(' ','T')):new Date();if(Number.isNaN(d.getTime()))return'';const z=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${z(d.getMonth()+1)}-${z(d.getDate())}T${z(d.getHours())}:${z(d.getMinutes())}`};
const dateTime=v=>{if(!v)return 'Nunca';const d=new Date(String(v).replace(' ','T'));if(Number.isNaN(d.getTime()))return String(v);return d.toLocaleString('es-VE',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});};
const v17Date=v=>{if(!v)return'—';const raw=String(v).trim();const d=new Date((/^\d{4}-\d{2}-\d{2}$/.test(raw)?raw+'T12:00:00':raw.replace(' ','T')));return Number.isNaN(d.getTime())?raw:d.toLocaleDateString('es-VE',{day:'2-digit',month:'short',year:'numeric'});};
const isSuperAdmin=/super\s*admin|superadministr/i.test(String(admin.role||''));
const isClientAdmin=/administrador\s+de\s+clientes/i.test(String(admin.role||''));
const can=key=>isSuperAdmin||permissions.includes('*')||permissions.includes(key);

function modulePermission(id){
  const map={
    resumen:'dashboard.view',analitica:'finance.view',centroalertas:'finance.view',solicitudes:'finance.applications.view',planes:'finance.view',cartera:'finance.view',clientes:'finance.clients.view',cobranza:'finance.view',pagos:'finance.payments.view',recibos:'finance.payments.view',riesgo:'finance.view',reportes:'finance.view',
    mapa:'gps.monitor.view',motos:'finance.clients.view',inventario:'finance.clients.view',entregas:'gps.vehicles.view',dispositivos:'gps.vehicles.view',activacion:'gps.settings.manage',comandos:'gps.commands.execute',grupos:'gps.settings.manage',geocercas:'gps.settings.manage',alertas:'gps.alerts.view',historial:'gps.history.view',recuperacion:'gps.alerts.view',
    usuarios:'users.view',auditoria:'audit.view',portal:'portal.manage',configuracion:'settings.manage',sitio:'finance.view',documentos:'dashboard.view',mantenimiento:'dashboard.view',comunicaciones:'dashboard.view'
  };
  return map[id]||'dashboard.view';
}
function canOpen(id){if(id==='motos')return cfg.area==='monitor'?can('gps.vehicles.view'):(can('finance.clients.view')||can('finance.view'));if(id==='inventario')return !isClientAdmin&&(can('finance.clients.view')||can('finance.view')||can('gps.vehicles.view'));if(id==='portal')return can('portal.manage')||can('portal.accounts.manage');return can(modulePermission(id));}

// Filtra el menu desde el origen, sin alterar la logica de cada modulo existente.
try{
  const filtered=menu.map(group=>[group[0],group[1].filter(item=>canOpen(item[0]))]).filter(group=>group[1].length);
  menu.splice(0,menu.length,...filtered);
}catch(_){/* V7.2 puede cargar sin menu durante mantenimiento */}

const oldNavigate=window.navigate||navigate;
window.navigate=navigate=function(id){
  if(!canOpen(id)){
    id=can('dashboard.view')?'resumen':(menu[0]?.[1]?.[0]?.[0]||'resumen');
    setTimeout(()=>toast('No tienes permiso para abrir ese modulo.','error'),60);
  }
  return oldNavigate(id);
};

async function request(url,options={}){
  const response=await fetch(url,{credentials:'same-origin',cache:'no-store',...options,headers:{Accept:'application/json',...(options.headers||{})}});
  let data={};try{data=await response.json()}catch(_){data={error:'Respuesta no valida del servidor.'}}
  if(!response.ok||data.ok===false)throw new Error(data.error||`Error HTTP ${response.status}`);
  return data;
}
const post=(url,body)=>request(url,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(body)});
function toast(message,type='ok'){
  const node=q('#toast');if(!node)return;
  node.innerHTML=`<i class="fa-solid ${type==='error'?'fa-triangle-exclamation':'fa-circle-check'}"></i>${safe(message)}`;
  node.classList.toggle('v8-toast-error',type==='error');node.classList.add('show');setTimeout(()=>node.classList.remove('show'),3500);
}
async function refreshWithFeedback(loader,message='Datos actualizados correctamente'){
  const active=document.activeElement&&document.activeElement.tagName==='BUTTON'?document.activeElement:null;
  const scope=active?.closest('.page')||document,original=active?active.innerHTML:'';
  if(active){active.disabled=true;active.innerHTML='<i class="fa-solid fa-rotate fa-spin"></i> Actualizando…';}
  try{await loader();const failed=scope.querySelector('.v8-state.denied');if(failed)toast(failed.querySelector('small')?.textContent||'No fue posible actualizar.','error');else toast(message);}
  catch(e){toast(e.message||'No fue posible actualizar.','error');}
  finally{if(active){active.disabled=false;active.innerHTML=original;}}
}
function loading(label='Cargando datos reales'){return `<div class="v8-state"><span class="v8-spinner"></span><b>${safe(label)}</b><small>Lectura puntual desde la base de datos · sin polling</small></div>`}
function denied(label='No tienes acceso a este modulo'){return `<div class="v8-state denied"><i class="fa-solid fa-lock"></i><b>${safe(label)}</b><small>Un administrador puede habilitar el permiso correspondiente.</small></div>`}
function statusInfo(account){
  const map={current:['Al día','good','fa-circle-check'],late:['En mora','warn','fa-clock'],critical:['Mora crítica','bad','fa-triangle-exclamation'],completed:['Completado','blue','fa-flag-checkered'],recovered:['Recuperada','purple','fa-shield-halved']};
  return map[account.status]||['En revisión','gray','fa-circle-info'];
}
function financeShell(title,sub,body=''){
  return `<div class="page v8-page"><section class="v8-hero"><div><span class="v8-eyebrow"><i class="fa-solid fa-chart-line"></i> DATOS REALES · BASE FINANCIERA</span><h2>${safe(title)}</h2><p>${safe(sub)}</p></div><div class="v8-hero-actions"><button onclick="gpFinanceRefresh()"><i class="fa-solid fa-rotate"></i> Actualizar</button>${can('finance.reports.export')?'<button onclick="gpFinanceExport()"><i class="fa-solid fa-file-csv"></i> Exportar cartera</button>':''}</div></section>${body||'<div id="v8FinanceRoot">'+loading()+'</div>'}</div>`;
}

views.resumen=()=>can('dashboard.view')?(can('finance.view')?financeShell('Resumen ejecutivo','Cartera importada desde Para Cargar la data.xlsx. Sin cifras demo.','<div id="v8FinanceRoot">'+loading('Preparando resumen ejecutivo')+'</div>'):`<div class="page v8-page"><section class="v8-hero"><div><span class="v8-eyebrow"><i class="fa-solid fa-shield-halved"></i> GRANDPRIX CONTROL 360</span><h2>Bienvenido, ${safe(admin.name||'usuario')}</h2><p>Tu acceso está limitado a los módulos autorizados para el rol ${safe(admin.role||'asignado')}.</p></div></section><div class="v8-state"><i class="fa-solid fa-user-shield"></i><b>Acceso por responsabilidades activo</b><small>Usa el menú para abrir únicamente las herramientas habilitadas.</small></div></div>`):denied();
