function paymentTable(list){if(!list.length)return '<div class="v8-empty">Todavía no hay movimientos posteriores a la importación inicial.</div>';return `<div class="v8-table-wrap"><table class="v8-table"><thead><tr><th>FECHA</th><th>CLIENTE</th><th>MONTO</th><th>BANCO / REFERENCIA</th><th>CUOTAS PAGADAS / ABONO</th><th>MORA REDUCIDA</th><th>ESTADO</th><th>OPERADOR</th><th></th></tr></thead><tbody>${list.map(p=>{const st=p.status==='confirmed'?['Conciliado','good']:p.status==='review'?['Por conciliar','warn']:['Rechazado','bad'];return `<tr><td>${safe(p.paid_at)}</td><td><b>${safe(p.full_name)}</b><br><small>${safe(p.plate||'')}</small></td><td><b>${paymentMoney(p)}</b><br><small>${safe(String(p.currency||'USD').toUpperCase())}</small></td><td>${safe(p.bank||'—')}<br><small>${safe(p.reference_number||'Sin referencia')}</small></td><td>${v31PaymentDistributionHtml(p)}</td><td>${p.late_reduced}</td><td><span class="v8-pill ${st[1]}">${st[0]}</span></td><td>${safe(p.created_by)}</td><td>${p.status==='review'&&can('finance.payments.reconcile')?`<div class="v8-inline-actions"><button class="v8-icon pay" onclick="gpPaymentReconcile(${p.id},'approved')" title="Aprobar"><i class="fa-solid fa-check"></i></button><button class="v8-icon danger" onclick="gpPaymentReconcile(${p.id},'rejected')" title="Rechazar"><i class="fa-solid fa-xmark"></i></button></div>`:''}</td></tr>`}).join('')}</tbody></table></div>`}
