function renderReports(){
  const root=q('#v8FinanceRoot');
  root.innerHTML=`<div class="v8-report-grid"><article class="panel"><i class="fa-solid fa-file-csv"></i><h3>Cartera completa</h3><p>${num(state.finance.metrics.total_records)} registros actuales con cliente, contrato, moto, cuotas, referente y GPS asignado.</p>${can('finance.reports.export')?'<button onclick="gpFinanceExport()"><i class="fa-solid fa-download"></i> Descargar CSV</button>':'<span class="v8-pill gray">Sin permiso de exportación</span>'}</article><article class="panel"><i class="fa-solid fa-users-viewfinder"></i><h3>Resumen por referente</h3><p>Calle, al día, x1, x2, x3, 4+, recuperadas, completadas y porcentajes.</p>${can('finance.reports.export')?'<button onclick="gpReferrerCsv()"><i class="fa-solid fa-download"></i> Exportar resumen</button>':'<span class="v8-pill gray">Sin permiso de exportación</span>'}</article><article class="panel"><i class="fa-solid fa-triangle-exclamation"></i><h3>Cartera en mora</h3><p>Filtra clientes con una o más cuotas vencidas para seguimiento.</p><button onclick="navigate('cobranza')"><i class="fa-solid fa-arrow-right"></i> Abrir cobranza</button></article></div>`;
}
function renderPublicSite(){
  const root=q('#v8FinanceRoot'),accounts=state.finance.accounts||[],models=[...new Set(accounts.map(a=>a.modelFamily).filter(x=>x&&String(x).toLowerCase()!=='sin modelo'))].sort();
  root.innerHTML=`<section class="v8-public-admin"><article class="v8-public-preview"><div><span class="v8-eyebrow"><i class="fa-solid fa-globe"></i> GRANDPRIX PÚBLICO</span><h2>Catálogo + financiamiento + solicitud digital</h2><p>El sitio público lee los modelos reales registrados en cartera y envía cada solicitud directamente al pipeline administrativo.</p><div class="v8-public-actions"><a href="public/" target="_blank" rel="noopener"><i class="fa-solid fa-arrow-up-right-from-square"></i> Abrir sitio público</a><button onclick="navigate('solicitudes')"><i class="fa-solid fa-file-signature"></i> Ver solicitudes</button></div></div><div class="v8-public-orbit"><i class="fa-solid fa-motorcycle"></i></div></article><div class="v8-public-metrics"><article><i class="fa-solid fa-motorcycle"></i><span><small>Modelos publicados</small><b>${models.length}</b><em>derivados de la data real</em></span></article><article><i class="fa-solid fa-list-ol"></i><span><small>Plan base</small><b>50</b><em>cuotas por solicitud</em></span></article><article><i class="fa-solid fa-route"></i><span><small>Flujo</small><b>4 etapas</b><em>perfil · docs · visita · oficina</em></span></article></div><section class="panel v8-panel"><div class="v8-panel-head"><div><h2>Modelos visibles</h2><p>El sitio no expone clientes ni placas; solo familias de modelos presentes en la cartera.</p></div></div><div class="v8-model-tags">${models.map(m=>`<span><i class="fa-solid fa-motorcycle"></i>${safe(m)}</span>`).join('')||'<p class="v8-empty">Sin modelos disponibles.</p>'}</div></section></section>`;
}
window.gpGlobalSearch=async term=>{term=String(term||'').trim();if(!term)return;try{await ensureFinance();state.search=term;navigate('clientes');setTimeout(()=>{const input=q('#v8FinanceSearch');if(input){input.value=term;renderClients()}},40)}catch(e){toast(e.message,'error')}};

function initials(name){return String(name||'GP').trim().split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase()||'GP'}

function ensureModal(){
  let node=q('#v8Modal');if(node)return node;
  node=document.createElement('div');node.id='v8Modal';node.className='v8-backdrop';node.innerHTML='<div class="v8-modal"><button class="v8-modal-x" onclick="gpV8Close()"><i class="fa-solid fa-xmark"></i></button><div id="v8ModalBody"></div></div>';document.body.appendChild(node);return node;
}
function openModal(html,wide=true){const node=ensureModal(),modal=node.querySelector('.v8-modal');modal.classList.remove('v25-dossier-modal');modal.classList.toggle('wide',wide);q('#v8ModalBody').innerHTML=html;node.classList.add('show')}
window.gpV8Close=()=>q('#v8Modal')?.classList.remove('show');
async function ensureInventoryCatalog(force=false){
  if(!v20Inventory||force){v20Inventory=await request(`${financeApi}?action=inventory`)}
  return Array.isArray(v20Inventory?.units)?v20Inventory.units:[];
}
function accountInventoryUnit(a=null){
  const units=v20Inventory?.units||[],accountId=Number(a?.id||0),plate=String(a?.plate||'').replace(/\s+/g,'').toUpperCase();
  return units.find(u=>Number(u.financeAccountId||0)===accountId)||(plate?units.find(u=>String(u.plate||'').replace(/\s+/g,'').toUpperCase()===plate):null)||null;
}
function accountInventoryOptions(a=null){
  const units=v20Inventory?.units||[],current=accountInventoryUnit(a),accountId=Number(a?.id||0);
  let html='<option value="">Sin motocicleta asignada todavía</option>';
  for(const u of units){
    const owner=Number(u.financeAccountId||0),mine=accountId>0&&owner===accountId,available=owner===0&&u.status==='available',selectable=mine||available;
    const gps=u.gpsDeviceId?`GPS ${u.gpsDeviceId}`:'sin GPS';
    const spec=[u.brand,u.model,u.year,u.color].filter(Boolean).join(' · ');
    const ownerText=!selectable?` · ASIGNADA A ${u.financeClient||u.portalClient||'otro cliente'}`:available?' · DISPONIBLE':' · ASIGNADA A ESTE CLIENTE';
    html+=`<option value="${Number(u.id)}" ${current&&Number(current.id)===Number(u.id)?'selected':''} ${selectable?'':'disabled'}>${safe(u.plate)} · ${safe(spec||u.model||'Moto')} · ${safe(gps)}${safe(ownerText)}</option>`;
  }
  return html;
}
function accountInventoryPreview(unit){
  if(!unit)return `<div class="v22-inventory-empty"><i class="fa-solid fa-motorcycle"></i><span><b>Sin motocicleta seleccionada</b><small>Selecciona una placa del Inventario maestro para precargar modelo y GPS.</small></span></div>`;
  const photo=typeof inventoryModelPhoto==='function'?inventoryModelPhoto(unit):{src:'assets/inventory-models/generic-default.png'},gps=unit.gpsDeviceId?`Device ID ${unit.gpsDeviceId}${unit.gpsUniqueId?' · IMEI '+unit.gpsUniqueId:''}`:'Sin GPS asignado';
  return `<div class="v22-inventory-preview"><div class="v22-inventory-photo"><img src="${photo.src}" alt="${safe(unit.model||'Moto')}" style="display:block;width:100%;height:145px;max-width:100%;object-fit:contain;object-position:center center" onerror="this.onerror=null;this.src='assets/inventory-models/generic-default.png'"><span>Foto referencial</span></div><div class="v22-inventory-data"><div><small>PLACA</small><b>${safe(unit.plate)}</b></div><div><small>MARCA / MODELO</small><b>${safe([unit.brand,unit.model].filter(Boolean).join(' ')||unit.model)}</b></div><div><small>AÑO / COLOR</small><b>${safe([unit.year,unit.color].filter(Boolean).join(' · ')||'Pendiente')}</b></div><div><small>CHASIS / VIN</small><b>${safe(unit.chassisSerial||'Pendiente')}</b></div><div><small>SERIAL MOTOR</small><b>${safe(unit.engineSerial||'Pendiente')}</b></div><div><small>GPS TRACCAR</small><b>${safe(gps)}</b></div></div></div>`;
}
function accountForm(a=null){
  const allAccounts=state.finance?.accounts||[],refs=[...new Set(allAccounts.map(x=>x.referrer).filter(Boolean))].sort(),current=accountInventoryUnit(a),locked=!!current&&Number(a?.id||0)>0;
  const model=current?[current.brand,current.model].filter(Boolean).join(' '):(a?.model||''),plate=current?.plate||a?.plate||'',gps=current?.gpsDeviceId||a?.gpsDeviceId||'',gpsLabel=current?.gpsLabel||a?.gpsLabel||'';
  openModal(`<span class="v8-eyebrow"><i class="fa-solid ${a?'fa-user-pen':'fa-user-plus'}"></i> ${a?'EDITAR EXPEDIENTE':'NUEVO CLIENTE'}</span><h2>${a?safe(a.fullName):'Registrar nuevo cliente'}</h2><p class="v8-modal-lead">Los datos de la motocicleta se toman directamente del Inventario maestro. Selecciona una placa y GRANDPRIX precargará modelo, especificaciones y GPS sin volver a escribirlos manualmente.</p><div id="v8AccountFeedback" class="v8-form-feedback" aria-live="polite"></div><form id="v8AccountForm" class="v8-form"><input type="hidden" name="id" value="${a?.id||0}"><input type="hidden" name="model" value="${safe(model)}"><input type="hidden" name="plate" value="${safe(plate)}"><input type="hidden" name="gpsDeviceId" value="${safe(gps)}"><input type="hidden" name="gpsLabel" value="${safe(gpsLabel)}"><div class="v8-form-grid"><label>Nombre completo<input name="fullName" required maxlength="160" value="${safe(a?.fullName||'')}"></label><label>Cédula<input name="identityDocument" maxlength="40" value="${safe(a?.identityDocument||'')}"></label><label>Teléfono<input name="phone" maxlength="40" value="${safe(a?.phone||'')}"></label><label>Refiere<input name="referrer" list="v8Refs" maxlength="100" value="${safe(a?.referrer||'')}"><datalist id="v8Refs">${refs.map(r=>`<option value="${safe(r)}">`).join('')}</datalist></label><label class="full">Dirección<input name="address" maxlength="300" value="${safe(a?.address||'')}"></label><label>Número de contrato<input name="contractNumber" maxlength="80" value="${safe(a?.contractNumber||'')}"></label><label>Fecha de inicio<input name="startDate" type="date" value="${safe(a?.startDate||'')}"></label><label>Cuota semanal USD · valor maestro<input name="weeklyAmount" type="number" min="0" step="0.01" value="${a?.weeklyAmount??''}" placeholder="0.00"></label><label>Monto financiado USD<input name="financedAmount" type="number" min="0" step="0.01" value="${a?.financedAmount??''}" placeholder="0.00"></label><label class="full v22-inventory-select">Motocicleta / placa desde Inventario<select name="inventoryId" id="v22AccountInventory">${accountInventoryOptions(a)}</select><small>${locked?'Esta unidad ya pertenece al cliente. Para cambiarla debes archivar/liberar primero la asignación anterior.':'Solo las unidades disponibles pueden seleccionarse; las asignadas a otros clientes aparecen bloqueadas.'}</small></label><div id="v22AccountInventoryPreview" class="full">${accountInventoryPreview(current)}</div><label>Cuotas pagadas<input name="paid" type="number" min="0" max="50" required readonly value="${a?.paid??0}"><small>Automático según pagos conciliados.</small></label><label>Cuotas en mora<input name="late" type="number" min="0" max="50" required readonly value="${a?.late??0}"><small>Automático según cronograma y saldos.</small></label><label>Abono / marca<input name="advanceNote" maxlength="80" value="${safe(a?.advanceNote||'')}"></label><label class="full">Observaciones<textarea name="notes" maxlength="1000">${safe(a?.notes||'')}</textarea></label></div><div class="v8-modal-actions">${a&&can('finance.clients.archive')?`<button type="button" class="danger" onclick="gpFinanceArchive(${a.id})"><i class="fa-solid fa-box-archive"></i> Archivar</button>`:''}<button class="primary"><i class="fa-solid ${a?'fa-floppy-disk':'fa-user-plus'}"></i> ${a?'Guardar cambios':'Agregar cliente'}</button></div></form>`);
  const selector=q('#v22AccountInventory'),form=q('#v8AccountForm'),preview=q('#v22AccountInventoryPreview');
  if(selector)selector.onchange=()=>{const unit=(v20Inventory?.units||[]).find(u=>Number(u.id)===Number(selector.value))||null;if(unit){form.elements.model.value=[unit.brand,unit.model].filter(Boolean).join(' ');form.elements.plate.value=unit.plate||'';form.elements.gpsDeviceId.value=unit.gpsDeviceId||'';form.elements.gpsLabel.value=unit.gpsLabel||''}else{form.elements.model.value='';form.elements.plate.value='';form.elements.gpsDeviceId.value='';form.elements.gpsLabel.value=''}if(preview)preview.innerHTML=accountInventoryPreview(unit)};
  q('#v8AccountForm').onsubmit=saveAccount;
}

async function saveAccount(e){
  e.preventDefault();
  const f=e.currentTarget,b=f.querySelector('.primary'),feedback=f.querySelector('#v8AccountFeedback');
  const raw=Object.fromEntries(new FormData(f)),isNew=Number(raw.id||0)===0;
  const old=(state.finance?.accounts||[]).find(x=>Number(x.id)===Number(raw.id));
  if(!can('finance.gps.assign')&&old){raw.gpsDeviceId=old.gpsDeviceId;raw.gpsLabel=old.gpsLabel}
  raw.id=Number(raw.id||0);raw.paid=Number(raw.paid||0);raw.late=Number(raw.late||0);raw.gpsDeviceId=raw.gpsDeviceId?Number(raw.gpsDeviceId):null;
  if(feedback){feedback.className='v8-form-feedback working';feedback.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i><span><b>Guardando cliente…</b><small>Validando datos, placa y GPS.</small></span>';}
  b.disabled=true;const original=b.innerHTML;b.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> Guardando…';
  try{
    const result=await post(`${financeApi}?action=save-account`,raw);
    const saved=result?.account;
    if(!saved||!Number(saved.id))throw new Error('El servidor no confirmó el cliente guardado. Actualiza e inténtalo nuevamente.');
    state.lastSavedAccountId=Number(saved.id);
    state.search='';state.risk='all';state.referrer='all';
    gpV8Close();
    await financeInit(true);
    showAccountSaved(saved,isNew,result.message||'Cliente guardado correctamente.');
  }catch(err){
    if(feedback){feedback.className='v8-form-feedback error';feedback.innerHTML=`<i class="fa-solid fa-circle-exclamation"></i><span><b>No se pudo guardar el cliente</b><small>${safe(err.message)}</small></span>`;}
    toast(err.message,'error');b.disabled=false;b.innerHTML=original;
  }
}
function showAccountSaved(account,isNew,message){
  const title=isNew?'Cliente agregado correctamente':'Cliente actualizado correctamente';
  openModal(`<section class="v8-save-success"><div class="v8-save-check"><i class="fa-solid fa-check"></i></div><span class="v8-eyebrow">OPERACIÓN COMPLETADA</span><h2>${title}</h2><p>${safe(message)}</p><div class="v8-save-client"><span class="v8-avatar">${safe(initials(account.fullName||''))}</span><div><b>${safe(account.fullName||'Cliente')}</b><small>${safe(account.identityDocument||'Cédula pendiente')}</small></div></div><div class="v8-save-meta"><span><small>Contrato</small><b>${safe(account.contractNumber||'Pendiente')}</b></span><span><small>Placa</small><b>${safe(account.plate||'Pendiente')}</b></span><span><small>GPS</small><b>${account.gpsDeviceId?'ID '+safe(account.gpsDeviceId):'Pendiente'}</b></span></div><div class="v8-save-actions"><button class="secondary" onclick="gpV8Close()"><i class="fa-solid fa-check"></i> Listo</button><button class="primary" onclick="gpV8Close();gpAccountStatement(${Number(account.id)})"><i class="fa-solid fa-address-card"></i> Ver cliente</button></div></section>`,false);
}
window.gpFinanceNew=async()=>{try{await ensureInventoryCatalog(true);accountForm()}catch(e){toast('No fue posible cargar el Inventario: '+e.message,'error')}};
window.gpFinanceEdit=async id=>{const a=(state.finance?.accounts||[]).find(x=>Number(x.id)===Number(id));if(!a)return;try{await ensureInventoryCatalog(true);accountForm(a)}catch(e){toast('No fue posible cargar el Inventario: '+e.message,'error')}};
function v25FileSize(bytes){const n=Number(bytes||0);if(n<1024)return n+' B';if(n<1048576)return (n/1024).toFixed(1)+' KB';return (n/1048576).toFixed(1)+' MB'}
function v25DossierFileUrl(file,download=false){return `${financeApi}?action=dossier-file&id=${Number(file?.id||0)}${download?'&download=1':''}`}
function v25DossierLatest(d,key){return (d?.checklist||[]).find(x=>x.key===key)?.latest||null}
function v25DossierPreview(d,fileId=0){
  const files=[...(d?.documents||[]),...(d?.paymentPdfs||[])],file=files.find(x=>Number(x.id)===Number(fileId))||v25DossierLatest(d,'contract')||v25DossierLatest(d,'identity')||files[0];
  if(!file)return `<div class="v25-preview-empty"><i class="fa-solid fa-file-circle-plus"></i><b>Sin documento seleccionado</b><small>Adjunta un archivo o selecciona uno existente para verlo aquí.</small></div>`;
  const url=v25DossierFileUrl(file),viewer=String(file.mime||'').startsWith('image/')?`<img src="${url}" alt="${safe(file.label)}">`:String(file.mime||'')==='application/pdf'?`<iframe src="${url}#toolbar=0&navpanes=0" title="${safe(file.label)}"></iframe>`:`<div class="v25-preview-empty"><i class="fa-solid fa-file"></i><b>${safe(file.originalName)}</b><small>Este tipo de archivo se abre en una pestaña nueva.</small></div>`;
  return `<div class="v25-preview-toolbar"><span><i class="fa-solid fa-eye"></i> Vista previa</span><div><button onclick="gpDossierOpenFile(${file.id})" title="Abrir"><i class="fa-solid fa-arrow-up-right-from-square"></i></button><button onclick="gpDossierDownloadFile(${file.id})" title="Descargar"><i class="fa-solid fa-download"></i></button></div></div><div class="v25-preview-frame">${viewer}</div><div class="v25-preview-meta"><span><i class="fa-solid fa-file"></i><b>${safe(file.originalName)}</b><small>${safe(file.mime)} · ${v25FileSize(file.size)}</small></span><div><small>Fecha de carga</small><b>${fmtDateTime(file.createdAt)}</b></div><div><small>Subido por</small><b>${safe(file.createdBy||'Sistema')}</b></div></div>`;
}
function v25ChecklistAction(a,item){
  if(item.key==='home_location')return `<button onclick="gpDossierLocation(${a.id})"><i class="fa-solid fa-location-crosshairs"></i>${item.complete?'Actualizar GPS':'Registrar ubicación GPS'}</button>`;
  if(item.complete&&item.latest)return `<div class="v25-row-actions"><button onclick="gpDossierSelectFile(${item.latest.id})"><i class="fa-solid fa-eye"></i> Ver</button>${can('finance.clients.edit')?`<button class="icon" onclick="gpDossierUpload(${a.id},'${item.key}')" title="Adjuntar otro"><i class="fa-solid fa-plus"></i></button>`:''}</div>`;
  if(!can('finance.clients.edit'))return '<span class="v25-no-action">Pendiente</span>';
  const labels={payment_pdf:'Adjuntar PDF de pago',contract:'Adjuntar contrato',identity:'Adjuntar cédula',residence_letter:'Adjuntar carta',house_front:'Subir foto'};
  return `<button onclick="gpDossierUpload(${a.id},'${item.key}')"><i class="fa-solid fa-cloud-arrow-up"></i>${safe(labels[item.key]||'Adjuntar archivo')}</button>`;
}
function v25ChecklistTable(a,d){return `<div class="v25-checklist-card"><div class="v25-card-head"><div><small>CHECKLIST DE DOCUMENTOS</small><h3>Documentación requerida</h3><p>Cada archivo queda identificado, fechado y ordenado dentro de la carpeta del cliente.</p></div><div class="v25-completion"><div class="v25-ring" style="--p:${Number(d.summary?.percent||0)}"><b>${Number(d.summary?.percent||0)}%</b></div><span><b>${Number(d.summary?.completeCount||0)}/${Number(d.summary?.total||6)}</b><small>completos</small></span></div></div><div class="v25-check-head"><span>Documento</span><span>¿Para qué se utiliza?</span><span>Estado</span><span>Archivo / Acción</span></div><div class="v25-check-rows">${(d.checklist||[]).map(item=>`<article><div class="v25-doc-name ${item.key}"><i class="fa-solid ${safe(item.icon)}"></i><span><b>${safe(item.label)}</b><small>${safe(item.description)}</small></span></div><p>${safe(item.purpose)}</p><span class="v25-doc-state ${item.complete?'complete':'pending'}"><i class="fa-solid ${item.complete?'fa-circle-check':'fa-clock'}"></i>${item.complete?'Completo':'Pendiente'}</span><div class="v25-doc-file">${item.latest?`<small>${safe(item.latest.originalName)}</small><em>${v25FileSize(item.latest.size)} · ${fmtDateTime(item.latest.createdAt)}</em>`:''}${v25ChecklistAction(a,item)}</div></article>`).join('')}</div><div class="v25-check-foot"><span>Progreso del checklist</span><div class="v25-progress"><i style="width:${Number(d.summary?.percent||0)}%"></i></div><b>${Number(d.summary?.completeCount||0)} de ${Number(d.summary?.total||6)} completados</b></div></div>`}
function v25FolderTree(d){const pays=(d.paymentPdfs||[]).slice(0,6);return `<div class="v25-folder-card"><div class="v25-card-head compact"><div><small>ESTRUCTURA DE CARPETAS DEL CLIENTE</small><h3>Organización en servidor</h3></div></div><div class="v25-tree"><div class="root"><i class="fa-solid fa-folder-open"></i><b>/CLIENTES/${safe(d.folderKey||'CLIENTE')}/</b></div><div class="level1"><i class="fa-solid fa-folder-open"></i><b>DOCUMENTOS</b></div>${['CEDULA_IDENTIDAD','CONTRATO','CARTA_RESIDENCIA','FOTO_FRENTE_CASA','UBICACION_GPS'].map(x=>`<div class="level2"><i class="fa-solid fa-folder"></i>${x}</div>`).join('')}<div class="level1"><i class="fa-solid fa-folder-open"></i><b>PAGOS_PDF</b><em>${(d.paymentPdfs||[]).length}</em></div>${pays.map(f=>`<button class="level2 file" onclick="gpDossierSelectFile(${f.id})"><i class="fa-solid fa-file-pdf"></i>${safe(f.originalName)}</button>`).join('')}${(d.paymentPdfs||[]).length>6?`<div class="level2 more">+ ${(d.paymentPdfs||[]).length-6} PDF adicionales</div>`:''}</div><div class="v25-storage"><span><small>Almacenamiento del expediente</small><b>${v25FileSize(d.storageBytes||0)}</b></span><div><i style="width:${Math.min(100,Number(d.storageBytes||0)/(50*1024*1024)*100)}%"></i></div></div></div>`}
function v25DetailChecklist(a,d){return `<div class="v25-detail-grid"><div>${v25ChecklistTable(a,d)}</div><div>${v25FolderTree(d)}</div><div id="v25DossierPreview" class="v25-preview-card">${v25DossierPreview(d,state.dossierSelectedFile)}</div></div>`}
function v25DetailDocuments(a,d){const docs=d.documents||[];return `<section class="v25-tab-panel"><div class="v25-tab-head"><div><small>DOCUMENTOS DEL CLIENTE</small><h3>Repositorio documental</h3><p>Todos los documentos del expediente, ordenados por tipo y fecha de carga.</p></div>${can('finance.clients.edit')?`<button onclick="gpDossierUpload(${a.id},'identity')"><i class="fa-solid fa-plus"></i> Adjuntar documento</button>`:''}</div><div class="v25-document-grid">${docs.length?docs.map(f=>`<article onclick="gpDossierSelectFile(${f.id});gpDossierTab('checklist')"><i class="fa-solid ${String(f.mime).startsWith('image/')?'fa-file-image':'fa-file-pdf'}"></i><span><b>${safe(f.label)}</b><small>${safe(f.originalName)}</small><em>${fmtDateTime(f.createdAt)} · ${v25FileSize(f.size)}</em></span><button onclick="event.stopPropagation();gpDossierOpenFile(${f.id})"><i class="fa-solid fa-eye"></i></button></article>`).join(''):'<div class="v8-empty">No hay documentos cargados todavía.</div>'}</div></section>`}
function v25DetailPayments(a,d){const files=d.paymentPdfs||[],receipts=a.receipts||[];return `<section class="v25-tab-panel"><div class="v25-tab-head"><div><small>PAGOS PDF ORGANIZADOS</small><h3>Recibos y comprobantes</h3><p>Solo se materializan recibos con movimientos reales. No se inventan PDFs históricos.</p></div>${can('finance.payments.create')?`<button onclick="gpV8Close();gpPaymentNew(${a.id})"><i class="fa-solid fa-money-bill-wave"></i> Registrar pago</button>`:''}</div><div class="v25-payment-summary"><article><small>Pagadas</small><b>${a.paid}/50</b></article><article><small>En mora</small><b>${a.late}</b></article><article><small>PDF disponibles</small><b>${files.length}</b></article><article><small>Recibos reales</small><b>${receipts.length}</b></article></div><div class="v25-payment-files">${files.length?files.map(f=>`<article><i class="fa-solid fa-file-pdf"></i><span><b>${safe(f.originalName)}</b><small>${fmtDateTime(f.createdAt)} · ${v25FileSize(f.size)}</small></span><button onclick="gpDossierOpenFile(${f.id})"><i class="fa-solid fa-eye"></i> Ver</button><button onclick="gpDossierDownloadFile(${f.id})"><i class="fa-solid fa-download"></i></button></article>`).join(''):'<div class="v8-empty">Todavía no existen recibos PDF reales para este cliente.</div>'}</div></section>`}
function v25DetailVisit(a,d){const photo=v25DossierLatest(d,'house_front'),loc=d.location;return `<section class="v25-tab-panel"><div class="v25-tab-head"><div><small>VISITA DOMICILIARIA</small><h3>Evidencia de residencia</h3><p>Foto del frente de la casa y ubicación GPS vinculadas al expediente.</p></div></div><div class="v25-visit-grid"><article class="v25-house-photo">${photo?`<img src="${v25DossierFileUrl(photo)}" alt="Frente de la casa"><div><b>Foto frente de la casa</b><small>${fmtDateTime(photo.createdAt)}</small></div>`:`<div class="empty"><i class="fa-solid fa-house-chimney"></i><b>Foto pendiente</b><small>Adjunta una imagen clara del frente de la vivienda.</small></div>`}${can('finance.clients.edit')?`<button onclick="gpDossierUpload(${a.id},'house_front')"><i class="fa-solid fa-camera"></i>${photo?'Actualizar foto':'Subir foto'}</button>`:''}</article><article class="v25-location-card"><i class="fa-solid fa-location-dot"></i><span><small>Ubicación GPS</small><b>${loc?.homeLat!=null&&loc?.homeLng!=null?`${Number(loc.homeLat).toFixed(6)}, ${Number(loc.homeLng).toFixed(6)}`:'Pendiente'}</b><p>${safe(loc?.homeAddress||a.address||'Dirección por confirmar')}</p><em>${loc?.homeLocationUpdatedAt?'Actualizada '+fmtDateTime(loc.homeLocationUpdatedAt):'Sin coordenadas registradas'}</em></span>${can('finance.clients.edit')?`<button onclick="gpDossierLocation(${a.id})"><i class="fa-solid fa-location-crosshairs"></i>${loc?.homeLat!=null?'Actualizar':'Registrar GPS'}</button>`:''}</article></div></section>`}
function v25DetailLocation(a,d){const loc=d.location;return `<section class="v25-tab-panel"><div class="v25-tab-head"><div><small>UBICACIÓN DE LA VIVIENDA</small><h3>Georreferencia del cliente</h3><p>Coordenadas conservadas dentro de DOCUMENTOS/UBICACION_GPS como evidencia del expediente.</p></div>${can('finance.clients.edit')?`<button onclick="gpDossierLocation(${a.id})"><i class="fa-solid fa-location-crosshairs"></i>${loc?.homeLat!=null?'Actualizar ubicación':'Registrar ubicación'}</button>`:''}</div><div class="v25-location-hero"><div class="pin"><i class="fa-solid fa-location-dot"></i></div><div><small>LATITUD</small><b>${loc?.homeLat!=null?Number(loc.homeLat).toFixed(7):'—'}</b></div><div><small>LONGITUD</small><b>${loc?.homeLng!=null?Number(loc.homeLng).toFixed(7):'—'}</b></div><div><small>DIRECCIÓN</small><b>${safe(loc?.homeAddress||a.address||'Pendiente')}</b></div><div class="full"><small>OBSERVACIONES</small><p>${safe(loc?.homeNotes||'Sin observaciones de ubicación.')}</p></div></div></section>`}
function v25DetailHistory(a,d){return `<section class="v25-tab-panel"><div class="v25-tab-head"><div><small>TRAZABILIDAD TOTAL</small><h3>Historial del expediente</h3><p>Cargas, PDFs, ubicación y acciones documentales conservadas en orden cronológico.</p></div></div><div class="v25-timeline">${(d.activity||[]).length?(d.activity||[]).map(x=>`<article><i class="fa-solid ${x.type==='payment_pdf'?'fa-file-pdf':x.type==='location'?'fa-location-dot':'fa-file-circle-check'}"></i><span><b>${safe(x.label)}</b><small>${fmtDateTime(x.date)} · ${safe(x.by||'Sistema')}</small></span>${x.fileId?`<button onclick="gpDossierOpenFile(${x.fileId})"><i class="fa-solid fa-eye"></i></button>`:''}</article>`).join(''):'<div class="v8-empty">Aún no hay actividad documental registrada.</div>'}</div></section>`}
function v25DossierTabContent(a,d,tab){if(tab==='documents')return v25DetailDocuments(a,d);if(tab==='payments')return v25DetailPayments(a,d);if(tab==='visit')return v25DetailVisit(a,d);if(tab==='location')return v25DetailLocation(a,d);if(tab==='history')return v25DetailHistory(a,d);return v25DetailChecklist(a,d)}
function openV25Dossier(a,d,tab='checklist'){
  state.dossierAccount=a;state.dossierDetail=d;state.dossierTab=tab;const st=statusInfo(a);if(!state.dossierSelectedFile){const candidate=v25DossierLatest(d,'contract')||v25DossierLatest(d,'identity')||d.documents?.[0]||d.paymentPdfs?.[0];state.dossierSelectedFile=Number(candidate?.id||0)}
  const tabs=[['checklist','fa-clipboard-check','Checklist'],['documents','fa-file-lines','Documentos'],['payments','fa-credit-card','Pagos'],['visit','fa-house','Visita'],['location','fa-location-dot','Ubicación'],['history','fa-clock-rotate-left','Historial']];
  openModal(`<section class="v25-dossier-shell"><div class="v25-dossier-breadcrumb"><span>Expediente 360</span><i class="fa-solid fa-chevron-right"></i><b>Detalle del expediente</b></div><header class="v25-dossier-header"><div class="v25-person"><span class="v25-avatar big">${safe(initials(a.fullName))}</span><div><h2>${safe(a.fullName)}</h2><p>${safe(a.identityDocument||'Cédula pendiente')} · ${safe(a.phone||'Teléfono pendiente')}</p><span class="v25-active"><i class="fa-solid fa-circle-check"></i> Cliente activo</span></div></div><div class="v25-head-fact bike"><img src="${safe(a.imagePath||'assets/moto-blue.png')}" alt=""><span><small>Moto asignada</small><b>${safe(a.model||'Sin modelo')}</b><em>${safe(a.plate||'Sin placa')}</em></span></div><div class="v25-head-fact"><span><small>Placa</small><b>${safe(a.plate||'Pendiente')}</b><em>${safe(a.modelFamily||'')}</em></span></div><div class="v25-head-fact"><span><small>GPS</small><b class="${a.gpsDeviceId?'good':''}">${a.gpsDeviceId?'Asignado':'Pendiente'}</b><em>${a.gpsDeviceId?'Device ID '+safe(a.gpsDeviceId):'Sin dispositivo'}</em></span></div><div class="v25-head-fact"><span><small>Contrato</small><b>${safe(a.contractNumber||'Pendiente')}</b><em>${safe(a.startDate||'Inicio pendiente')}</em></span></div><div class="v25-head-fact"><span><small>Riesgo de mora</small>${v25RiskLabel(a)}<em>${a.late} semana(s) vencida(s)</em></span></div><div class="v25-head-quick"><small>Acciones rápidas</small><div>${can('finance.clients.edit')?`<button onclick="gpV8Close();gpFinanceEdit(${a.id})" title="Editar"><i class="fa-solid fa-pen"></i></button>`:''}${can('finance.payments.create')?`<button onclick="gpV8Close();gpPaymentNew(${a.id})" title="Pago"><i class="fa-solid fa-money-bill-wave"></i></button>`:''}<button onclick="gpDossierSync(${a.id})" title="Sincronizar"><i class="fa-solid fa-rotate"></i></button></div></div></header><nav id="v25DossierTabs" class="v25-dossier-tabs">${tabs.map(([key,icon,label])=>`<button class="${tab===key?'active':''}" onclick="gpDossierTab('${key}')"><i class="fa-solid ${icon}"></i>${label}</button>`).join('')}</nav><div id="v25DossierContent">${v25DossierTabContent(a,d,tab)}</div></section>`,true);const modal=q('#v8Modal .v8-modal');if(modal)modal.classList.add('v25-dossier-modal');
}
window.gpAccountStatement=async (id,tab='checklist')=>{try{state.dossierSelectedFile=0;const [r,d]=await Promise.all([request(`${financeApi}?action=account&id=${encodeURIComponent(id)}`),request(`${financeApi}?action=client-dossier&accountId=${encodeURIComponent(id)}`)]);openV25Dossier(r.account,d.dossier,tab)}catch(e){toast(e.message,'error')}};
window.gpDossierTab=tab=>{if(!state.dossierAccount||!state.dossierDetail)return;state.dossierTab=tab;qa('#v25DossierTabs button').forEach(b=>b.classList.toggle('active',b.getAttribute('onclick')?.includes(`'${tab}'`)));const body=q('#v25DossierContent');if(body)body.innerHTML=v25DossierTabContent(state.dossierAccount,state.dossierDetail,tab)};
window.gpDossierSelectFile=id=>{state.dossierSelectedFile=Number(id||0);const preview=q('#v25DossierPreview');if(preview&&state.dossierDetail)preview.innerHTML=v25DossierPreview(state.dossierDetail,state.dossierSelectedFile)};
window.gpDossierOpenFile=id=>window.open(`${financeApi}?action=dossier-file&id=${Number(id)}`,'_blank','noopener');
window.gpDossierDownloadFile=id=>window.open(`${financeApi}?action=dossier-file&id=${Number(id)}&download=1`,'_blank','noopener');
window.gpDossierUpload=(accountId,docKey)=>{const def={payment_pdf:['PDF de pagos','Selecciona un comprobante o recibo PDF correspondiente a este cliente.','application/pdf'],contract:['Contrato','Adjunta el contrato de financiamiento firmado.','application/pdf,image/jpeg,image/png,image/webp'],identity:['Cédula de identidad','Adjunta una copia legible de la cédula. Puedes volver a cargar otro archivo si necesitas ambas caras.','application/pdf,image/jpeg,image/png,image/webp'],residence_letter:['Carta de residencia','Adjunta la constancia o carta de residencia vigente.','application/pdf,image/jpeg,image/png,image/webp'],house_front:['Foto frente de la casa','Adjunta una fotografía clara del frente de la vivienda.','image/jpeg,image/png,image/webp']}[docKey];if(!def)return;openModal(`<span class="v8-eyebrow"><i class="fa-solid fa-paperclip"></i> ADJUNTAR AL EXPEDIENTE</span><h2>${safe(def[0])}</h2><p class="v8-modal-lead">${safe(def[1])} El archivo se guardará automáticamente en la subcarpeta correcta del cliente.</p><div class="v25-upload-destination"><i class="fa-solid fa-folder-tree"></i><span><small>DESTINO</small><b>${docKey==='payment_pdf'?'PAGOS_PDF':'DOCUMENTOS / '+safe(def[0].toUpperCase().replace(/ /g,'_'))}</b></span></div><form id="v25DossierUploadForm" class="v8-form"><input type="hidden" name="accountId" value="${accountId}"><input type="hidden" name="docKey" value="${safe(docKey)}"><label class="full v8-file-drop"><i class="fa-solid fa-cloud-arrow-up"></i><span><b>Seleccionar ${safe(def[0].toLowerCase())}</b><small>Máximo 12 MB · el sistema valida el tipo de archivo</small></span><input name="file" type="file" accept="${safe(def[2])}" required></label><button class="v8-submit"><i class="fa-solid fa-folder-plus"></i> Adjuntar y ordenar archivo</button></form>`);q('#v25DossierUploadForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('.v8-submit'),fd=new FormData(f);b.disabled=true;try{const r=await request(`${financeApi}?action=dossier-upload`,{method:'POST',headers:{'X-CSRF-Token':csrf},body:fd});toast(r.message);state.dossierSummaries=null;gpV8Close();setTimeout(()=>gpAccountStatement(accountId,state.dossierTab||'checklist'),80)}catch(err){toast(err.message,'error');b.disabled=false}}};
window.gpDossierLocation=accountId=>{const loc=state.dossierDetail?.location||{};openModal(`<span class="v8-eyebrow"><i class="fa-solid fa-location-dot"></i> UBICACIÓN GPS DE LA CASA</span><h2>Registrar residencia del cliente</h2><p class="v8-modal-lead">Guarda las coordenadas de la vivienda. GRANDPRIX conservará un archivo JSON dentro de DOCUMENTOS / UBICACION_GPS y lo mostrará en el checklist.</p><form id="v25LocationForm" class="v8-form"><div class="v8-form-grid"><label>Latitud<input name="latitude" type="number" step="0.0000001" min="-90" max="90" required value="${loc.homeLat??''}"></label><label>Longitud<input name="longitude" type="number" step="0.0000001" min="-180" max="180" required value="${loc.homeLng??''}"></label><label class="full">Dirección<input name="address" maxlength="300" value="${safe(loc.homeAddress||state.dossierAccount?.address||'')}"></label><label class="full">Observaciones<textarea name="notes" maxlength="1000">${safe(loc.homeNotes||'')}</textarea></label></div><div class="v25-location-actions"><button type="button" id="v25UseLocation"><i class="fa-solid fa-location-crosshairs"></i> Usar ubicación de este dispositivo</button><button class="v8-submit"><i class="fa-solid fa-floppy-disk"></i> Guardar ubicación</button></div></form>`);const f=q('#v25LocationForm'),use=q('#v25UseLocation');if(use)use.onclick=()=>{if(!navigator.geolocation){toast('Este navegador no permite obtener ubicación.','error');return}use.disabled=true;use.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> Obteniendo…';navigator.geolocation.getCurrentPosition(pos=>{f.elements.latitude.value=pos.coords.latitude.toFixed(7);f.elements.longitude.value=pos.coords.longitude.toFixed(7);use.disabled=false;use.innerHTML='<i class="fa-solid fa-location-crosshairs"></i> Ubicación capturada'},err=>{toast(err.message||'No fue posible obtener la ubicación.','error');use.disabled=false;use.innerHTML='<i class="fa-solid fa-location-crosshairs"></i> Usar ubicación de este dispositivo'},{enableHighAccuracy:true,timeout:12000})};f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('.v8-submit'),v=Object.fromEntries(new FormData(f));v.accountId=Number(accountId);v.latitude=Number(v.latitude);v.longitude=Number(v.longitude);b.disabled=true;try{const r=await post(`${financeApi}?action=dossier-location`,v);toast(r.message);state.dossierSummaries=null;gpV8Close();setTimeout(()=>gpAccountStatement(accountId,'location'),80)}catch(err){toast(err.message,'error');b.disabled=false}}};
window.gpDossierSync=async accountId=>{try{const r=await post(`${financeApi}?action=dossier-sync`,{accountId:Number(accountId)});toast(r.message);state.dossierSummaries=null;state.dossierDetail=r.dossier;if(state.dossierAccount)openV25Dossier(state.dossierAccount,r.dossier,state.dossierTab||'checklist')}catch(e){toast(e.message,'error')}};

window.gpFinanceArchive=async id=>{if(!confirm('¿Archivar y desactivar este cliente? Su historial NO se elimina, pero se cerrará su acceso Mi GRANDPRIX y la motocicleta/placa/GPS quedarán liberados para una futura reasignación.'))return;try{const r=await post(`${financeApi}?action=archive-account`,{id});toast(r.message);gpV8Close();await financeInit(true)}catch(e){toast(e.message,'error')}};
function paymentForm(accountId=0){
  const accounts=(state.finance?.accounts||[]).filter(a=>a.status!=='completed');const selected=accounts.find(a=>Number(a.id)===Number(accountId));
  openModal(`<span class="v8-eyebrow">REGISTRAR MOVIMIENTO</span><h2>Pago / conciliación</h2><p class="v8-modal-lead">${can('finance.payments.reconcile')?'Puedes aplicarlo inmediatamente o enviarlo a revisión.':'Tu registro quedará pendiente de conciliación antes de modificar las cuotas.'}</p><form id="v8PaymentForm" class="v8-form"><div class="v8-form-grid"><label class="full">Cliente<select name="accountId" required><option value="">Seleccionar</option>${accounts.map(a=>`<option value="${a.id}" ${Number(accountId)===Number(a.id)?'selected':''}>${safe(a.fullName)} · ${safe(a.plate||a.model||'sin moto')} · mora ${a.late}</option>`).join('')}</select></label><label>Fecha<input type="date" name="paidAt" required value="${today()}"></label><label>Monto USD (opcional)<input type="number" name="amount" min="0" step="0.01" placeholder="0.00"></label><label>Cuotas a sumar<input type="number" name="installmentsApplied" min="0" max="50" value="1" required></label><label>Mora a reducir<input type="number" name="lateReduced" min="0" max="50" value="${selected?.late?1:0}" required></label><label>Banco<input name="bank" maxlength="100"></label><label>Referencia<input name="reference" maxlength="100"></label>${can('finance.payments.reconcile')?'<label class="full">Tratamiento<select name="paymentMode"><option value="confirmed">Conciliar y aplicar ahora</option><option value="review">Guardar pendiente de conciliación</option></select></label>':'<input type="hidden" name="paymentMode" value="review">'}<label class="full">Observaciones<textarea name="notes" maxlength="500"></textarea></label></div><button class="v8-submit"><i class="fa-solid fa-money-bill-wave"></i> Guardar movimiento</button></form>`);
  q('#v8PaymentForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('.v8-submit');b.disabled=true;const v=Object.fromEntries(new FormData(f));v.accountId=Number(v.accountId);v.installmentsApplied=Number(v.installmentsApplied||0);v.lateReduced=Number(v.lateReduced||0);v.amount=v.amount===''?null:Number(v.amount);v.needsReview=v.paymentMode==='review';delete v.paymentMode;try{const r=await post(`${financeApi}?action=record-payment`,v);toast(r.message);gpV8Close();await financeInit(true)}catch(err){toast(err.message,'error');b.disabled=false}};
}
window.gpPaymentNew=paymentForm;
window.gpPaymentReconcile=async(id,decision)=>{const label=decision==='approved'?'aprobar y aplicar este pago':'rechazar este movimiento';if(!confirm(`¿Deseas ${label}?`))return;try{const r=await post(`${financeApi}?action=reconcile-payment`,{id,decision});toast(r.message);await financeInit(true)}catch(e){toast(e.message,'error')}};
window.gpFinanceRefresh=()=>refreshWithFeedback(async()=>{state.dossierSummaries=null;await financeInit(true)},'Módulo actualizado con datos reales');
window.gpFinanceExport=()=>{window.location.href=`${financeApi}?action=export`};
window.gpReferrerCsv=()=>{
  if(!can('finance.reports.export')){toast('No tienes permiso para exportar reportes.','error');return}
  if(!state.finance)return;const rows=[['Refiere','Calle','Al dia','x1','x2','x3','4 o mas','REC','COMPL','Cuotas en mora','% Al dia','% En Mora','% Mora Critica'],...state.finance.referrers.map(r=>[r.name,r.street,r.current,r.x1,r.x2,r.x3,r.x4plus,r.recovered,r.completed,r.lateInstallments,r.pctCurrent,r.pctLate,r.pctCritical])];
  const csv='\ufeff'+rows.map(row=>row.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(';')).join('\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='grandprix-resumen-referentes.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
  post(`${financeApi}?action=audit-event`,{module:'reports',action:'referrer_summary_download',eventType:'download',summary:'Descargó el resumen por referente en CSV.',label:'Resumen por referente'}).catch(()=>{});
};

async function alertsInit(){
  const root=q('#v18AlertsRoot');if(!root)return;root.innerHTML=loading('Calculando alertas financieras');
  try{const r=await request(`${financeApi}?action=alerts`),d=r.data||{},m=d.metrics||{},list=d.alerts||[];root.innerHTML=renderAlertCenter(d,m,list);updateAlertBadge(m);}
  catch(e){root.innerHTML=`<div class="v8-state denied"><i class="fa-solid fa-triangle-exclamation"></i><b>No se pudieron calcular las alertas</b><small>${safe(e.message)}</small></div>`}
}
function updateAlertBadge(m){const badge=q('#gpAlertBadge');if(!badge)return;const n=Number(m?.critical||0)+Number(m?.paymentsReview||0);badge.textContent=n>99?'99+':String(n);badge.classList.toggle('show',n>0)}
function renderAlertCenter(d,m,list){
  const cards=[['fa-triangle-exclamation','Mora crítica',m.critical||0,'critical','3 o más semanas vencidas'],['fa-fire','Recuperación urgente',m.urgent||0,'urgent','5 o más semanas vencidas'],['fa-hourglass-half','Pagos por conciliar',m.paymentsReview||0,'review','requieren validación'],['fa-calendar-day','Próximo miércoles',m.dueNextWednesday||0,'calendar',d.nextWednesday||'—']];
  return `<section class="v18-alert-kpis">${cards.map(c=>`<article class="${c[3]}"><i class="fa-solid ${c[0]}"></i><span><small>${c[1]}</small><b>${num(c[2])}</b><em>${safe(c[4])}</em></span></article>`).join('')}</section><section class="v18-alert-summary"><div><i class="fa-solid fa-clock"></i><span><b>Actualizado con hora Venezuela</b><small>${safe(fmtDateTime(d.generatedAt))} · ${safe(d.timezone||'America/Caracas')}</small></span></div><div class="v18-alert-mini"><span><b>${num(m.clientsLate||0)}</b><small>clientes en mora</small></span><span><b>${num(m.lateWeeks||0)}</b><small>semanas vencidas</small></span><span><b>${num(m.lateOne||0)}</b><small>mora x1</small></span><span><b>${num(m.lateTwo||0)}</b><small>mora x2</small></span></div></section><section class="v18-notification-grid"><button onclick="navigate('cobranza')" class="critical"><i class="fa-solid fa-triangle-exclamation"></i><span><b>${num(m.critical||0)} clientes críticos</b><small>Revisar cola priorizada de cobranza</small></span><i class="fa-solid fa-arrow-right"></i></button><button onclick="navigate('pagos')" class="review"><i class="fa-solid fa-money-check-dollar"></i><span><b>${num(m.paymentsReview||0)} pagos por conciliar</b><small>Validar antes de aplicar semanas y recibos</small></span><i class="fa-solid fa-arrow-right"></i></button><button onclick="navigate('planes')" class="calendar"><i class="fa-solid fa-calendar-day"></i><span><b>${num(m.dueNextWednesday||0)} cuotas el miércoles</b><small>${safe(d.nextWednesday||'')} · calendario oficial GRANDPRIX</small></span><i class="fa-solid fa-arrow-right"></i></button>${can('audit.view')?`<button onclick="navigate('auditoria')" class="audit"><i class="fa-solid fa-fingerprint"></i><span><b>Auditoría de eventos</b><small>Revisar accesos, cambios y descargas</small></span><i class="fa-solid fa-arrow-right"></i></button>`:''}</section><section class="panel v8-panel v18-alert-panel"><div class="v8-panel-head"><div><span class="v10-section-kicker">COLA DE ATENCIÓN</span><h2>Clientes que requieren seguimiento</h2><p>Ordenados de mayor a menor riesgo financiero.</p></div><button onclick="navigate('cobranza')"><i class="fa-solid fa-hand-holding-dollar"></i> Abrir cobranza</button></div>${list.length?`<div class="v18-alert-list">${list.map(alertClientCard).join('')}</div>`:'<div class="v8-empty"><i class="fa-solid fa-circle-check"></i> No hay clientes en mora actualmente.</div>'}</section>`;
}
function alertClientCard(a){const cls=a.severity||'attention';return `<article class="v18-alert-client ${cls}"><div class="v18-alert-rank"><i class="fa-solid ${cls==='urgent'?'fa-fire':cls==='critical'?'fa-triangle-exclamation':'fa-clock'}"></i></div><div class="v18-alert-client-main"><span class="v8-pill ${cls==='urgent'||cls==='critical'?'bad':'warn'}">${safe(a.label)}</span><h3>${safe(a.client)}</h3><p>${safe(a.identity||'Cédula pendiente')} · ${safe(a.phone||'Teléfono pendiente')}</p><div class="v18-alert-tags"><span><i class="fa-solid fa-motorcycle"></i>${safe(a.model||'Sin modelo')} · ${safe(a.plate||'Sin placa')}</span><span><i class="fa-solid fa-file-contract"></i>${safe(a.contract||'Sin contrato')}</span><span><i class="fa-solid fa-user-group"></i>${safe(a.referrer||'Sin referente')}</span></div></div><div class="v18-alert-debt"><small>Semanas vencidas</small><b>${a.late}</b><span>${a.weeklyAmount!=null?money(Number(a.weeklyAmount)*Number(a.late))+' estimado':'Monto por confirmar'}</span></div><div class="v18-alert-dates"><span><small>Vencimiento más antiguo</small><b>${safe(a.oldestLateDue||'Histórico sin fecha')}</b></span><span><small>Último pago</small><b>${safe(a.lastPaymentAt||'Sin movimiento V17')}</b></span></div><div class="v18-alert-actions"><button onclick="gpAccountStatement(${a.accountId})"><i class="fa-solid fa-address-card"></i> Expediente</button>${can('finance.payments.create')?`<button class="primary" onclick="gpPaymentNew(${a.accountId})"><i class="fa-solid fa-money-bill-wave"></i> Registrar pago</button>`:''}</div></article>`}
window.gpAlertsRefresh=()=>refreshWithFeedback(()=>alertsInit(),'Centro de alertas actualizado');

async function auditInit(){
  const root=q('#v8AuditRoot');if(!root)return;root.innerHTML=loading('Leyendo auditoría de eventos');
  try{const params=new URLSearchParams({action:'event-audit'}),f=state.filters.audit;for(const [k,v] of Object.entries(f))if(String(v||'').trim()!=='')params.set(k,String(v).trim());const r=await request(`${financeApi}?${params}`);root.innerHTML=renderAuditEvents(r);bindAuditFilters();}
  catch(e){root.innerHTML=`<div class="v8-state denied"><i class="fa-solid fa-triangle-exclamation"></i><b>No se pudo leer la auditoría</b><small>${safe(e.message)}</small></div>`}
}
function renderAuditEvents(r){const events=r.events||[],sum=r.summary||{},users=r.users||[],mods=r.modules||[],types=r.types||[],f=state.filters.audit;return `<section class="v18-audit-kpis"><article><i class="fa-solid fa-list-check"></i><span><small>Eventos hoy</small><b>${num(sum.total||0)}</b></span></article><article><i class="fa-solid fa-right-to-bracket"></i><span><small>Inicios de sesión</small><b>${num(sum.logins||0)}</b></span></article><article><i class="fa-solid fa-file-arrow-down"></i><span><small>Descargas</small><b>${num(sum.downloads||0)}</b></span></article><article><i class="fa-solid fa-pen-to-square"></i><span><small>Cambios / flujo</small><b>${num(sum.changes||0)}</b></span></article></section><section class="panel v8-panel v18-audit-panel"><form id="v18AuditFilters" class="v18-audit-filters"><label>Desde<input type="date" name="from" value="${safe(f.from)}"></label><label>Hasta<input type="date" name="to" value="${safe(f.to)}"></label><label>Usuario<select name="user"><option value="">Todos</option>${users.map(u=>`<option value="${safe(u.user_email)}" ${f.user===u.user_email?'selected':''}>${safe(u.user_name||u.user_email)}</option>`).join('')}</select></label><label>Módulo<select name="module"><option value="">Todos</option>${mods.map(x=>`<option ${f.module===x?'selected':''}>${safe(x)}</option>`).join('')}</select></label><label>Tipo<select name="type"><option value="">Todos</option>${types.map(x=>`<option ${f.type===x?'selected':''}>${safe(x)}</option>`).join('')}</select></label><label class="search">Buscar<input name="search" value="${safe(f.search)}" placeholder="acción, usuario, entidad..."></label><button><i class="fa-solid fa-filter"></i> Filtrar</button><button type="button" class="v20-filter-clear" onclick="gpAuditFiltersClear()"><i class="fa-solid fa-filter-circle-xmark"></i> Limpiar</button></form><div class="v18-timezone-note"><i class="fa-solid fa-clock"></i> Toda la auditoría se presenta en <b>hora Venezuela · America/Caracas (UTC-4)</b>.</div>${events.length?`<div class="v8-table-wrap"><table class="v8-table v18-audit-table"><thead><tr><th>FECHA / HORA VE</th><th>USUARIO</th><th>TIPO</th><th>MÓDULO</th><th>ACCIÓN</th><th>ENTIDAD</th><th>IP / DISPOSITIVO</th><th>RESUMEN</th></tr></thead><tbody>${events.map(auditRow).join('')}</tbody></table></div>`:'<div class="v8-empty">No hay eventos para los filtros seleccionados.</div>'}</section>`}
function auditRow(e){const ua=String(e.user_agent||'');const device=/Mobile|Android|iPhone/i.test(ua)?'Móvil':'Escritorio';const who=e.user_name||e.user_email||e.actor_type||'Sistema';return `<tr><td><b>${safe(e.event_at)}</b><small>${safe(e.timezone_name||'America/Caracas')}</small></td><td><b>${safe(who)}</b><small>${safe(e.user_email||e.actor_type||'')}</small><em>${safe(e.user_role||e.actor_type||'')}</em></td><td><span class="v18-event-type ${safe(e.event_type)}">${safe(e.event_type)}</span></td><td><span class="v8-pill blue">${safe(e.module_key)}</span></td><td>${safe(e.action_key)}</td><td>${safe(e.entity_type||'—')}${e.entity_id?' #'+e.entity_id:''}</td><td><b>${safe(e.ip_address||'—')}</b><small>${device} · ${safe(e.http_method||'')}</small></td><td>${safe(e.summary||'')}<small class="route">${safe(e.route||'')}</small></td></tr>`}
function bindAuditFilters(){const form=q('#v18AuditFilters');if(!form)return;const sync=()=>{const fd=new FormData(form);for(const k of Object.keys(state.filters.audit))state.filters.audit[k]=String(fd.get(k)||'')};form.onsubmit=e=>{e.preventDefault();sync();auditInit()};form.querySelectorAll('select,input[type="date"]').forEach(el=>el.onchange=()=>{sync();auditInit()});const search=form.querySelector('input[name="search"]');if(search)search.oninput=()=>{state.filters.audit.search=search.value};}
window.gpAuditFiltersClear=()=>{state.filters.audit={from:'',to:'',user:'',module:'',type:'',search:''};auditInit()};
window.gpAuditRefresh=()=>refreshWithFeedback(()=>auditInit(),'Auditoría actualizada');
window.gpAuditExport=()=>{const params=new URLSearchParams({action:'event-audit-export'});for(const [k,v] of Object.entries(state.filters.audit))if(String(v||'').trim())params.set(k,String(v).trim());window.location.href=`${financeApi}?${params}`};

async function usersInit(force=false){
  const root=q('#v8UsersRoot');if(!root)return;root.innerHTML=loading('Cargando usuarios y permisos');
  try{if(!state.users||force)state.users=await request(`${usersApi}?action=overview`);renderUsers()}
  catch(e){root.innerHTML=`<div class="v8-state denied"><i class="fa-solid fa-triangle-exclamation"></i><b>No se pudo cargar Usuarios</b><small>${safe(e.message)}</small></div>`}
}
function renderUsers(){
  const root=q('#v8UsersRoot'),d=state.users,users=d.users||[],roles=d.roles||[],permTotal=(d.permissions||[]).length;
  const active=users.filter(u=>u.status==='active').length,blocked=users.filter(u=>u.status!=='active').length,custom=users.filter(u=>Number(u.override_count||0)>0).length;
  root.innerHTML=`<section class="v8-kpis v10-security-kpis"><article class="v8-kpi blue"><i class="fa-solid fa-user-shield"></i><div><small>Usuarios habilitados</small><strong>${active}</strong><span>accesos administrativos activos</span></div></article><article class="v8-kpi green"><i class="fa-solid fa-users-gear"></i><div><small>Roles configurados</small><strong>${roles.length}</strong><span>perfiles de responsabilidad</span></div></article><article class="v8-kpi purple"><i class="fa-solid fa-key"></i><div><small>Permisos controlables</small><strong>${permTotal}</strong><span>acciones granularmente protegidas</span></div></article><article class="v8-kpi amber"><i class="fa-solid fa-fingerprint"></i><div><small>Accesos personalizados</small><strong>${custom}</strong><span>${blocked} cuentas suspendidas o bloqueadas</span></div></article></section><div class="v10-security-layout"><section class="panel v8-panel v10-users-panel"><div class="v8-panel-head"><div><span class="v10-section-kicker">IDENTIDAD Y ACCESO</span><h2>Usuarios administrativos</h2><p>Control individual de sesión, rol, estado y alcance efectivo</p></div><span class="v10-total-badge">${users.length} cuentas</span></div><div class="v10-user-list">${users.map(u=>{const ep=(u.effective_permissions||[]).length,customized=Number(u.override_count||0)>0;return `<button ${can('users.edit')?`onclick="gpUserEdit(${u.id})"`:'disabled'} class="v10-user-row"><span class="v10-user-avatar">${safe(initials(u.full_name))}<i class="${u.status}"></i></span><span class="v10-user-identity"><b>${safe(u.full_name)}</b><small>${safe(u.email)}</small><em><i class="fa-solid fa-shield-halved"></i>${safe(u.role_name||'Sin rol')}${customized?' · personalizado':''}</em></span><span class="v10-user-meta"><small>Último acceso</small><b>${safe(dateTime(u.last_login_at))}</b></span><span class="v10-user-meta permissions"><small>Permisos</small><b>${ep}</b></span><span class="v10-user-status ${safe(u.status)}">${u.status==='active'?'<i class="fa-solid fa-circle-check"></i> Activo':u.status==='blocked'?'<i class="fa-solid fa-ban"></i> Bloqueado':'<i class="fa-solid fa-pause"></i> Suspendido'}</span><i class="fa-solid ${can('users.edit')?'fa-chevron-right':'fa-eye'} v10-row-arrow"></i></button>`}).join('')}</div></section><section class="panel v8-panel v10-roles-panel"><div class="v8-panel-head"><div><span class="v10-section-kicker">GOBIERNO DE PERMISOS</span><h2>Roles y alcance</h2><p>Plantillas reutilizables para separar responsabilidades</p></div></div><div class="v10-role-list">${roles.map(r=>{const count=(r.permissions||[]).length,coverage=permTotal?Math.min(100,(count/permTotal)*100):0;return `<article><div class="v10-role-head"><span class="v10-role-icon"><i class="fa-solid ${r.name==='Superadministrador'?'fa-crown':'fa-user-lock'}"></i></span><div><b>${safe(r.name)}</b><small>${r.is_system?'Rol protegido del sistema':'Rol personalizado'}</small></div>${r.is_system?'<em>SISTEMA</em>':'<em class="custom">PERSONAL</em>'}</div><p>${safe(r.description||'Sin descripción')}</p><div class="v10-role-count"><span><b>${count}</b><small>permisos</small></span><strong>${Math.round(coverage)}%</strong></div><div class="v10-role-progress"><i style="width:${coverage}%"></i></div>${can('users.permissions')&&r.name!=='Superadministrador'?`<button onclick="gpRoleEdit(${r.id})"><i class="fa-solid fa-sliders"></i> Administrar acceso</button>`:''}</article>`}).join('')}</div></section></div>`;
}
function groupedPermissions(selected=[]){
  const groups={};(state.users.permissions||[]).forEach(p=>{(groups[p.module_key]??=[]).push(p)});const set=new Set(selected);
  return Object.entries(groups).map(([module,items])=>`<section class="v8-perm-group"><h4>${safe(moduleLabel(module))}</h4>${items.map(p=>`<label><input type="checkbox" name="permission" value="${safe(p.permission_key)}" ${set.has(p.permission_key)?'checked':''}><span><b>${safe(p.label)}</b><small>${safe(p.description||'')}</small></span></label>`).join('')}</section>`).join('');
}
function moduleLabel(m){return ({direccion:'Dirección',finanzas:'Finanzas',usuarios:'Usuarios',seguridad:'Auditoría y seguridad',gps:'GPS y seguridad',portal:'Portal cliente',configuracion:'Configuración'})[m]||m}
function userForm(u=null){
  const roles=state.users.roles||[];const effective=u?.effective_permissions||[];const custom=Number(u?.override_count||0)>0;
  openModal(`<span class="v8-eyebrow">${u?'EDITAR USUARIO':'NUEVO USUARIO'}</span><h2>${u?safe(u.full_name):'Crear acceso administrativo'}</h2><p class="v8-modal-lead">El rol define una base. Si activas personalización puedes marcar exactamente cada permiso.</p><form id="v8UserForm" class="v8-form"><input type="hidden" name="id" value="${u?.id||0}"><div class="v8-form-grid"><label>Nombre completo<input name="name" required maxlength="160" value="${safe(u?.full_name||'')}"></label><label>Correo<input name="email" type="email" required value="${safe(u?.email||'')}"></label><label>${u?'Nueva clave (opcional)':'Clave inicial'}<input name="password" type="password" ${u?'':'required'} minlength="8" autocomplete="new-password"></label><label>Estado<select name="status"><option value="active" ${u?.status!=='suspended'?'selected':''}>Activo</option><option value="suspended" ${u?.status==='suspended'?'selected':''}>Suspendido</option><option value="blocked" ${u?.status==='blocked'?'selected':''}>Bloqueado</option></select></label><label class="full">Rol<select name="roleId" required>${roles.map(r=>`<option value="${r.id}" ${Number(u?.role_id)===Number(r.id)?'selected':''}>${safe(r.name)}</option>`).join('')}</select></label>${can('users.permissions')?`<label class="v8-custom-perms full"><input id="v8Customize" type="checkbox" name="customizePermissions" ${custom?'checked':''}><span><b>Personalizar permisos de este usuario</b><small>Lo marcado abajo reemplaza el alcance del rol para esta cuenta.</small></span></label><div id="v8PermissionEditor" class="v8-permission-editor full ${custom?'show':''}">${groupedPermissions(effective)}</div>`:''}</div><button class="v8-submit"><i class="fa-solid fa-user-shield"></i> Guardar usuario</button></form>`);
  const customBox=q('#v8Customize');if(customBox)customBox.onchange=()=>q('#v8PermissionEditor').classList.toggle('show',customBox.checked);
  q('#v8UserForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('.v8-submit'),fd=new FormData(f);const v={id:Number(fd.get('id')||0),name:fd.get('name'),email:fd.get('email'),password:fd.get('password'),status:fd.get('status'),roleId:Number(fd.get('roleId')),customizePermissions:!!fd.get('customizePermissions'),permissions:fd.getAll('permission')};b.disabled=true;try{const r=await post(`${usersApi}?action=save-user`,v);toast(r.message);gpV8Close();await usersInit(true)}catch(err){toast(err.message,'error');b.disabled=false}};
}
window.gpUserNew=()=>{if(can('users.create'))userForm()};window.gpUserEdit=id=>{if(!can('users.edit'))return;const u=(state.users?.users||[]).find(x=>Number(x.id)===Number(id));if(u)userForm(u)};
function roleForm(r=null){
  openModal(`<span class="v8-eyebrow">${r?'EDITAR ROL':'NUEVO ROL'}</span><h2>${r?safe(r.name):'Crear rol personalizado'}</h2><form id="v8RoleForm" class="v8-form"><input type="hidden" name="id" value="${r?.id||0}"><div class="v8-form-grid"><label>Nombre del rol<input name="name" required maxlength="100" value="${safe(r?.name||'')}"></label><label>Descripción<input name="description" maxlength="300" value="${safe(r?.description||'')}"></label><div class="v8-permission-editor show full">${groupedPermissions(r?.permissions||[])}</div></div><button class="v8-submit"><i class="fa-solid fa-users-gear"></i> Guardar rol</button></form>`);
  q('#v8RoleForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('.v8-submit'),fd=new FormData(f);const v={id:Number(fd.get('id')||0),name:fd.get('name'),description:fd.get('description'),permissions:fd.getAll('permission')};b.disabled=true;try{const res=await post(`${usersApi}?action=save-role`,v);toast(res.message);gpV8Close();await usersInit(true)}catch(err){toast(err.message,'error');b.disabled=false}};
}
window.gpRoleNew=()=>roleForm();window.gpRoleEdit=id=>{const r=(state.users?.roles||[]).find(x=>Number(x.id)===Number(id));if(r)roleForm(r)};window.gpUsersRefresh=()=>refreshWithFeedback(()=>usersInit(true),'Usuarios y permisos actualizados');


/* GRANDPRIX V17 · Pagos por semana + recibos automáticos. */
try{
  const creditGroup=menu.find(group=>group[0]==='CRÉDITOS');
  if(creditGroup&&can('finance.payments.view')&&!creditGroup[1].some(item=>item[0]==='recibos')){
    const pos=creditGroup[1].findIndex(item=>item[0]==='pagos');
    creditGroup[1].splice(pos>=0?pos+1:creditGroup[1].length,0,['recibos','fa-receipt','Recibos de pago']);
  }
}catch(_){/* menú ya inicializado */}
views.recibos=()=>can('finance.payments.view')?`<div class="page v8-page"><section class="v8-hero v17-receipt-hero"><div><span class="v8-eyebrow"><i class="fa-solid fa-receipt"></i> GRANDPRIX · RECIBOS AUTOMÁTICOS</span><h2>Recibos de pago semanal</h2><p>Cada pago conciliado genera su comprobante con cliente, moto, contrato, semanas pagadas y cuotas vencidas que permanezcan pendientes.</p></div><div class="v8-hero-actions">${can('finance.payments.create')?'<button class="v17-primary" onclick="gpPaymentNew()"><i class="fa-solid fa-plus"></i> Registrar pago</button>':''}<button onclick="gpFinanceRefresh()"><i class="fa-solid fa-rotate"></i> Actualizar</button></div></section><div id="v8FinanceRoot">${loading('Leyendo recibos')}</div></div>`:denied();

renderFinanceCurrent=function(){
  if(!state.finance)return;
  const renderers={resumen:renderDashboard,analitica:renderAnalytics,motos:renderExpediente360,planes:renderPlans,cartera:renderPortfolio,clientes:renderClients,cobranza:renderCollections,pagos:renderPaymentsV17,recibos:renderReceiptsV17,riesgo:renderRisk,reportes:renderReports,sitio:renderPublicSite};
  (renderers[current]||renderDashboard)();
};

function v17ReceiptPending(r){return Array.isArray(r.pendingWeeks)?r.pendingWeeks:[]}
function v17ReceiptPaid(r){return Array.isArray(r.paidWeeks)?r.paidWeeks:[]}
function v28ReceiptPartial(r){return Array.isArray(r.partialWeeks)?r.partialWeeks:[]}
function v28PaymentMoney(value,currency='USD'){const n=Number(value||0);return String(currency||'USD').toUpperCase()==='BS'?`Bs. ${n.toLocaleString('es-VE',{minimumFractionDigits:2,maximumFractionDigits:2})}`:money(n)}
function v28ReceiptMoney(r){return v28PaymentMoney(r.amount,r.currency)}
function v28PartialText(r){const p=v28ReceiptPartial(r)[0];if(!p)return'';return `Semana ${Number(p.weekNumber)}: ${v28PaymentMoney(p.allocated,'USD')} abonados de ${v28PaymentMoney(p.amountDue,'USD')} (${Number(p.paidPercentageAfter||0).toFixed(0)}%) · saldo ${v28PaymentMoney(p.balanceAfter,'USD')}`}
function v17ReceiptStatus(r){return v17ReceiptPending(r).length?['Con pendientes','warn','fa-triangle-exclamation']:['Al día','good','fa-circle-check']}
function v17ReceiptCard(r,compact=false){
  const st=v17ReceiptStatus(r),paid=v17ReceiptPaid(r),pending=v17ReceiptPending(r),partial=v28ReceiptPartial(r),week=paid.length?paid[paid.length-1]:(partial[0]?.weekNumber??'—'),weekLabel=paid.length?'ÚLTIMA SEMANA COMPLETADA':partial.length?'SEMANA CON ABONO':'APLICACIÓN';
  const partialStrip=partial.length?`<div class="v17-pending-strip has-pending"><span><i class="fa-solid fa-chart-pie"></i>Abono parcial</span><div><em>${safe(v28PartialText(r))}</em></div></div>`:'';
  return `<article class="v17-receipt-card ${compact?'compact':''}"><header><div><small>${safe(r.receiptNumber)}</small><b>${safe(r.clientName)}</b><span>${safe(r.identityDocument||'Cédula pendiente')} · ${safe(r.phone||'Teléfono pendiente')}</span></div><span class="v8-pill ${st[1]}"><i class="fa-solid ${st[2]}"></i>${st[0]}</span></header><div class="v17-receipt-main"><div class="v17-week-box"><small>${weekLabel}</small><strong>${week}</strong></div><div class="v17-receipt-facts"><span><small>Monto recibido</small><b>${v28ReceiptMoney(r)}</b></span><span><small>Equiv. USD</small><b>${money(r.amountUsd??r.amount)}</b></span><span><small>Fecha</small><b>${v17Date(r.paidAt)}</b></span><span><small>Próximo saldo</small><b>${r.nextAmount!=null?money(r.nextAmount):'—'}</b></span></div></div>${partialStrip}<div class="v17-pending-strip ${pending.length?'has-pending':'clear'}"><span><i class="fa-solid ${pending.length?'fa-triangle-exclamation':'fa-circle-check'}"></i>${pending.length?'Semanas vencidas que aún tienen saldo':'Sin semanas vencidas'}</span><div>${pending.map(w=>`<b>${w}</b>`).join('')||'<em>AL DÍA</em>'}</div></div><footer><span><small>Contrato</small><b>${safe(r.contractNumber||'—')}</b></span><span><small>Placa</small><b>${safe(r.plate||'—')}</b></span><div><button onclick="gpReceiptOpen(${r.id})"><i class="fa-solid fa-eye"></i> Ver recibo</button><button onclick="gpReceiptPrint(${r.id})" title="Imprimir"><i class="fa-solid fa-print"></i></button><button onclick="gpReceiptPdf(${r.id})" title="Descargar PDF"><i class="fa-solid fa-file-pdf"></i></button></div></footer></article>`;
}
function filterReceiptsV17(receipts){const f=state.filters.receipts,term=String(f.search||'').trim().toLowerCase();return receipts.filter(r=>{if(term&&!([r.clientName,r.receiptNumber,r.contractNumber,r.plate,r.identityDocument,r.model].some(v=>String(v||'').toLowerCase().includes(term))))return false;const debt=v17ReceiptPending(r).length>0;if(f.status==='debt'&&!debt)return false;if(f.status==='clear'&&debt)return false;return true})}
function updateReceiptResults(){const receipts=state.finance?.receipts||[],filtered=filterReceiptsV17(receipts),grid=q('#v17ReceiptGrid'),count=q('#v17ReceiptCount');if(grid)grid.innerHTML=filtered.length?filtered.map(r=>v17ReceiptCard(r)).join(''):'<div class="v8-empty">No hay recibos que coincidan con los filtros.</div>';if(count)count.textContent=`${filtered.length} de ${receipts.length}`;}
function bindReceiptFilters(){const input=q('#v17ReceiptSearch'),status=q('#v17ReceiptStatus');if(input)input.oninput=()=>{state.filters.receipts.search=input.value;updateReceiptResults()};if(status)status.onchange=()=>{state.filters.receipts.status=status.value;updateReceiptResults()};}
