 accountSelect.onchange=()=>{const id=Number(accountSelect.value||0),a=accounts.find(x=>Number(x.id)===id);if(clientSearch)clientSearch.value=a?.fullName||'';renderClientSearch();loadContext(id)};if(clientSearch){clientSearch.oninput=renderClientSearch;clientSearch.onfocus=renderClientSearch;clientSearch.onkeydown=e=>{if(e.key==='Enter'){const term=normalizeClientTerm(clientSearch.value),found=accounts.filter(a=>accountSearchText(a).includes(term));if(term&&found.length===1){e.preventDefault();const a=found[0];if(!Array.from(accountSelect.options).some(o=>Number(o.value)===Number(a.id)))accountSelect.insertAdjacentHTML('beforeend',accountOption(a));accountSelect.value=String(a.id);clientSearch.value=a.fullName||'';renderClientSearch();loadContext(Number(a.id));clientSearch.blur()}}};}if(clientClear)clientClear.onclick=()=>{clientSearch.value='';accountSelect.innerHTML='<option value="">Seleccionar cliente</option>'+accounts.map(accountOption).join('');accountSelect.value='';context=null;renderClientSearch();loadContext(0);clientSearch.focus()};amount.oninput=preview;currency.onchange=()=>{rateLabel.style.display=currency.value==='BS'?'':'none';rate.required=currency.value==='BS';preview()};rate.oninput=preview;
